mapper.select:
SELECT s.station_id AS stationId, s.station_name AS name, s.address, s.latitude AS lat, s.longitude AS lng, s.total_piles AS totalPiles, (SELECT COUNT(*) FROM stad_charging_pile p WHERE p.station_id = s.station_id AND p.pile_status = '0') AS freePiles, (SELECT COUNT(*) FROM stad_charging_pile p WHERE p.station_id = s.station_id AND p.pile_status = '1') AS occupyingPiles, s.parking_fee AS parkFee, s.open_time AS openTime, s.close_time AS closeTime, s.images, s.images AS imageUrl, (SELECT rp.total_price FROM stad_charging_rate_period rp WHERE rp.rate_id = (SELECT r.rate_id FROM stad_charging_rate r WHERE r.station_id = s.station_id AND r.is_active = 1 LIMIT 1) ORDER BY rp.sort_order LIMIT 1) AS price, (SELECT rp.energy_price FROM stad_charging_rate_period rp WHERE rp.rate_id = (SELECT r.rate_id FROM stad_charging_rate r WHERE r.station_id = s.station_id AND r.is_active = 1 LIMIT 1) ORDER BY rp.sort_order LIMIT 1) AS electricPrice, (SELECT rp.service_fee FROM stad_charging_rate_period rp WHERE rp.rate_id = (SELECT r.rate_id FROM stad_charging_rate r WHERE r.station_id = s.station_id AND r.is_active = 1 LIMIT 1) ORDER BY rp.sort_order LIMIT 1) AS servicePrice, ROUND(6371 * 2 * ASIN(SQRT( POW(SIN((#{lat} - s.latitude) * PI() / 360), 2) + COS(#{lat} * PI() / 180) * COS(s.latitude * PI() / 180) * POW(SIN((#{lng} - s.longitude) * PI() / 360), 2) )), 1) AS distance, s.facilities_info AS facilitiesInfo, s.station_status AS stationStatus, (SELECT COUNT(*) FROM stad_charging_pile p WHERE p.station_id = s.station_id AND (p.pile_type LIKE '%快%' OR p.pile_type LIKE '%直流%' OR p.pile_type LIKE '%DC%' OR p.pile_type LIKE '%120%' OR p.pile_type LIKE '%60%')) AS fastCount, (SELECT COUNT(*) FROM stad_charging_pile p WHERE p.station_id = s.station_id AND (p.pile_type LIKE '%慢%' OR p.pile_type LIKE '%交流%' OR p.pile_type LIKE '%AC%' OR p.pile_type LIKE '%7kW%' OR p.pile_type LIKE '%3.5kW%')) AS slowCount FROM stad_charging_station s WHERE s.station_status = '1' AND s.total_piles > 0 ORDER BY
distance s.station_id s.create_time
ASC DESC LIMIT #{offset}, #{limit}

SELECT 
FROM stad_charging_station s
WHERE s.station_id = #{stationId}

mapper.update:
UPDATE stad_charging_station
SET available_piles = (
    SELECT COUNT(*) FROM stad_charging_pile
    WHERE station_id = #{stationId} AND pile_status = '0'
),
occupying_piles = (
    SELECT COUNT(*) FROM stad_charging_pile
    WHERE station_id = #{stationId} AND pile_status = '1'
)
WHERE station_id = #{stationId}
